  var svg=old||document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','bonds');svg.setAttribute('aria-hidden','true');svg.setAttribute('data-sig',sig);svg.style.height=(L.scrollHeight||0)+'px';svg.innerHTML=GSDEF+segs.join('')+sl+rg;if(!old)L.insertBefore(svg,L.firstChild);
